+			}
+			return nil, stderr.Bytes(), err
+		}
+		if pkg.ImportPath == "" || pkg.Name == "" {
+			continue
+		}
+		info.names[pkg.ImportPath] = pkg.Name
+	}
+	return info, stderr.Bytes(), nil
