+package main
+
+import (
+	"bytes"
+	"context"
+	"errors"
+	"fmt"
+	"go/ast"
+	"go/format"
+	"go/parser"
+	"go/printer"
+	"go/token"
+	"io/fs"
+	"log"
+	"os"
+	"path"
+	"path/filepath"
+	"sort"
+	"strings"
+)
+
+type processor struct {
+	cfg         config
+	fs          interface{ Usage() }
+	pkgCache    map[string]*packageInfo
+	checkedOut  bool
+	anyChanged  bool
+	hadError    bool
+}
+
+type usageError struct {
+	message string
+}
+
+func (e usageError) Error() string { return e.message }
+
+func fmtUsageErrorf(format string, args ...any) error {
+	return usageError{message: fmt.Sprintf(format, args...)}
+}
+
+func newProcessor(cfg config, fs interface{ Usage() }) *processor {
+	return &processor{
+		cfg:      cfg,
+		fs:       fs,
+		pkgCache: make(map[string]*packageInfo),
+	}
+}
+
+func (p *processor) run() int {
+	for _, input := range p.cfg.paths {
+		log.Printf("Processing %s", input)
+		if !p.checkedOut {
+			if !validOutputMode(p.cfg.output) {
+				log.Printf("invalid output %q specified", p.cfg.output)
+				return 1
+			}
+			p.checkedOut = true
+		}
+
+		files, err := p.expandInput(input)
+		if err != nil {
+			log.Printf("Failed to fix file: %v", err)
+			p.hadError = true
+			continue
+		}
+
+		for _, filePath := range files {
+			result, err := p.processFile(filePath)
+			if err != nil {
+				var uerr usageError
+				if errors.As(err, &uerr) {
+					p.fs.Usage()
+					log.Printf("%v", err)
+					return 1
+				}
+				log.Printf("Failed to fix file: %v", err)
+				p.hadError = true
+				continue
+			}
+
+			if result.changed {
+				p.anyChanged = true
+			}
+
+			if err := p.emitResult(result); err != nil {
+				log.Printf("Failed to fix file: %v", err)
+				p.hadError = true
+			}
+		}
+	}
+
+	if p.hadError {
+		return 1
+	}
+	if p.cfg.setExitStatus && p.anyChanged {
+		return 1
+	}
+	return 0
+}
+
+type fileResult struct {
+	path     string
+	original []byte
+	output   []byte
+	changed  bool
+}
+
+func (p *processor) emitResult(result fileResult) error {
+	switch p.cfg.output {
+	case "stdout":
+		if p.cfg.listDiff {
+			if result.changed {
+				_, err := fmt.Fprintln(os.Stdout, result.path)
+				return err
+			}
+			_, err := os.Stdout.Write(result.output)
+			return err
+		}
+		_, err := os.Stdout.Write(result.output)
+		return err
+	case "file":
+		if p.cfg.listDiff {
+			_, err := fmt.Fprintln(os.Stdout, result.path)
+			return err
+		}
+		return os.WriteFile(result.path, result.output, 0o644)
+	case "write":
+		if p.cfg.listDiff {
+			if _, err := fmt.Fprintln(os.Stdout, result.path); err != nil {
+				return err
+			}
+		}
+		return os.WriteFile(result.path, result.output, 0o644)
+	default:
+		return nil
+	}
+}
+
+func (p *processor) processFile(filePath string) (fileResult, error) {
+	original, err := os.ReadFile(filePath)
+	if err != nil {
+		return fileResult{}, err
+	}
+
+	projectName := p.cfg.projectName
+	if projectName == "" {
+		projectName, err = inferProjectName(filePath)
+		if err != nil {
+			return fileResult{}, fmtUsageErrorf("Could not determine project name for path %s: %v", filePath, err)
+		}
+	}
+
+	if !p.cfg.applyGenerated && isGeneratedFile(original) {
+		return fileResult{
+			path:     filePath,
+			original: original,
+			output:   original,
+			changed:  false,
+		}, nil
+	}
+
+	fset := token.NewFileSet()
+	file, err := parser.ParseFile(fset, filePath, original, parser.ParseComments)
+	if err != nil {
+		return fileResult{}, fmt.Errorf("file has invalid Go source content, use -excludes flag to skip this file: %w", err)
+	}
+
+	var pkgInfo *packageInfo
+	if p.cfg.rmUnused || p.cfg.setAlias {
+		pkgInfo, err = p.packageInfoFor(filePath)
+		if err != nil {
+			return fileResult{}, err
+		}
+	}
+
+	rewritten, err := rewriteFile(file, fset, original, projectName, p.cfg, pkgInfo)
+	if err != nil {
+		return fileResult{}, err
+	}
+
+	return fileResult{
+		path:     filePath,
+		original: original,
+		output:   rewritten,
+		changed:  !bytes.Equal(original, rewritten),
+	}, nil
+}
+
+func (p *processor) packageInfoFor(filePath string) (*packageInfo, error) {
+	dir := packageDir(filePath)
+	if info, ok := p.pkgCache[dir]; ok {
+		return info, nil
+	}
+
+	info, stderr, err := loadPackageInfo(context.Background(), dir)
+	if err != nil {
+		if len(stderr) > 0 {
+			_, _ = os.Stderr.Write(stderr)
+		}
+		return nil, errors.New("package has an errors")
+	}
+
+	p.pkgCache[dir] = info
+	return info, nil
+}
+
+func rewriteFile(file *ast.File, fset *token.FileSet, original []byte, projectName string, cfg config, pkgInfo *packageInfo) ([]byte, error) {
+	cImports, nonCEntries, inlineComments := collectImports(file)
+
+	if cfg.rmUnused && len(nonCEntries) > 0 {
+		nonCEntries = removeUnusedImports(file, nonCEntries, pkgInfo)
+	}
+
+	if cfg.setAlias && len(nonCEntries) > 0 {
+		applyAliases(nonCEntries, pkgInfo)
+	}
+
+	ordered, segments := sortImports(nonCEntries, cfg, projectName)
+	file.Comments = filterComments(file, inlineComments, cImports, ordered)
+	rebuildDecls(file, cImports, ordered)
+	updateFileImports(file, cImports, ordered)
+
+	printed, err := printFile(fset, file)
+	if err != nil {
+		return nil, err
+	}
+
+	if needsGroupedImportRewrite(segments) {
+		block := buildGroupedImportBlock(segments)
+		printed, err = replaceNonCImportDecl(printed, block)
+		if err != nil {
+			return nil, err
+		}
+	}
+
+	if cfg.format {
+		formatted, err := format.Source(printed)
+		if err != nil {
+			return nil, err
+		}
+		printed = formatted
+	}
+
+	return printed, nil
+}
+
+func collectImports(file *ast.File) ([]*ast.GenDecl, []importEntry, map[*ast.CommentGroup]struct{}) {
+	var cDecls []*ast.GenDecl
+	var entries []importEntry
+	inlineComments := map[*ast.CommentGroup]struct{}{}
+
+	for _, decl := range file.Decls {
+		gen, ok := decl.(*ast.GenDecl)
+		if !ok || gen.Tok != token.IMPORT {
+			continue
+		}
+
+		onlyC := true
+		for _, spec := range gen.Specs {
+			importSpec := spec.(*ast.ImportSpec)
+			importPath := strings.Trim(importSpec.Path.Value, `"`)
+			if importPath != "C" {
+				onlyC = false
+				break
+			}
+		}
+		if onlyC {
+			cDecls = append(cDecls, cloneImportDecl(gen))
+			continue
+		}
+
+		for _, spec := range gen.Specs {
+			importSpec := spec.(*ast.ImportSpec)
+			importPath := strings.Trim(importSpec.Path.Value, `"`)
+			if importPath == "C" {
+				cDecls = append(cDecls, singleImportDecl(importSpec, gen.Doc))
+				continue
+			}
+
+			entry := importEntry{
+				path:      importPath,
+				pathValue: importSpec.Path.Value,
+				original:  importSpec,
+			}
+			if importSpec.Name != nil {
+				entry.name = importSpec.Name.Name
+			}
+			if importSpec.Comment != nil {
+				entry.inline = joinCommentGroup(importSpec.Comment)
+				inlineComments[importSpec.Comment] = struct{}{}
+			}
+			entries = append(entries, entry)
+		}
+	}
+
+	return cDecls, entries, inlineComments
+}
+
+func removeUnusedImports(file *ast.File, entries []importEntry, pkgInfo *packageInfo) []importEntry {
+	for _, entry := range entries {
+		if entry.name == "_" || entry.name == "." {
+			return entries
+		}
+	}
+
+	used := map[string]struct{}{}
+	ast.Inspect(file, func(n ast.Node) bool {
+		switch node := n.(type) {
+		case *ast.ImportSpec:
+			return false
+		case *ast.SelectorExpr:
+			if ident, ok := node.X.(*ast.Ident); ok {
+				used[ident.Name] = struct{}{}
+			}
+		}
+		return true
+	})
+
+	out := make([]importEntry, 0, len(entries))
+	for _, entry := range entries {
+		name := entry.name
+		if name == "" {
+			name = pkgInfo.names[entry.path]
+			if name == "" {
+				name = fallbackPackageName(entry.path)
+			}
+		}
+		if _, ok := used[name]; ok {
+			out = append(out, entry)
+		}
+	}
+	return out
+}
+
+func applyAliases(entries []importEntry, pkgInfo *packageInfo) {
+	for i := range entries {
+		if entries[i].name != "" || !needsAlias(entries[i].path) {
+			continue
+		}
+		name := pkgInfo.names[entries[i].path]
+		if name == "" {
+			name = fallbackPackageName(entries[i].path)
+		}
+		entries[i].name = name
+	}
+}
+
+func filterComments(file *ast.File, inline map[*ast.CommentGroup]struct{}, cDecls []*ast.GenDecl, entries []importEntry) []*ast.CommentGroup {
+	keep := map[*ast.CommentGroup]struct{}{}
+	for group := range inline {
+		keep[group] = struct{}{}
+	}
+	for _, entry := range entries {
+		if entry.original.Comment != nil {
+			keep[entry.original.Comment] = struct{}{}
+		}
+	}
+
+	var importRanges [][2]token.Pos
+	for _, decl := range file.Decls {
+		gen, ok := decl.(*ast.GenDecl)
+		if !ok || gen.Tok != token.IMPORT {
+			continue
+		}
+
+		hasNonC := false
+		for _, spec := range gen.Specs {
+			if strings.Trim(spec.(*ast.ImportSpec).Path.Value, `"`) != "C" {
+				hasNonC = true
+				break
+			}
+		}
+		if hasNonC {
+			importRanges = append(importRanges, [2]token.Pos{gen.Pos(), gen.End()})
+		}
+	}
+
+	for _, decl := range cDecls {
+		if decl.Doc != nil {
+			keep[decl.Doc] = struct{}{}
+		}
+		for _, spec := range decl.Specs {
+			importSpec := spec.(*ast.ImportSpec)
+			if importSpec.Doc != nil {
+				keep[importSpec.Doc] = struct{}{}
+			}
+			if importSpec.Comment != nil {
+				keep[importSpec.Comment] = struct{}{}
+			}
+		}
+	}
+
+	comments := make([]*ast.CommentGroup, 0, len(file.Comments))
+	for _, group := range file.Comments {
+		if _, ok := keep[group]; ok {
+			comments = append(comments, group)
+			continue
+		}
+		if !inAnyRange(group.Pos(), importRanges) {
+			comments = append(comments, group)
+		}
+	}
+
+	sort.Slice(comments, func(i, j int) bool {
+		return comments[i].Pos() < comments[j].Pos()
+	})
+	return comments
+}
+
+func inAnyRange(pos token.Pos, ranges [][2]token.Pos) bool {
+	for _, pair := range ranges {
+		if pos >= pair[0] && pos < pair[1] {
+			return true
+		}
+	}
+	return false
+}
+
+func rebuildDecls(file *ast.File, cDecls []*ast.GenDecl, entries []importEntry) {
+	var rebuilt []ast.Decl
+	inserted := false
+
+	for _, decl := range file.Decls {
+		gen, ok := decl.(*ast.GenDecl)
+		if ok && gen.Tok == token.IMPORT {
+			if !inserted {
+				for _, cDecl := range cDecls {
+					rebuilt = append(rebuilt, cDecl)
+				}
+				if len(entries) > 0 {
+					rebuilt = append(rebuilt, buildImportDecl(entries))
+				}
+				inserted = true
+			}
+			continue
+		}
+		rebuilt = append(rebuilt, decl)
+	}
+
+	if !inserted && (len(cDecls) > 0 || len(entries) > 0) {
+		var withImports []ast.Decl
+		for _, cDecl := range cDecls {
+			withImports = append(withImports, cDecl)
+		}
+		if len(entries) > 0 {
+			withImports = append(withImports, buildImportDecl(entries))
+		}
+		withImports = append(withImports, rebuilt...)
+		rebuilt = withImports
+	}
+
+	file.Decls = rebuilt
+}
+
+func updateFileImports(file *ast.File, cDecls []*ast.GenDecl, entries []importEntry) {
+	imports := make([]*ast.ImportSpec, 0, len(cDecls)+len(entries))
+	for _, decl := range cDecls {
+		for _, spec := range decl.Specs {
+			imports = append(imports, spec.(*ast.ImportSpec))
+		}
+	}
+	for _, entry := range entries {
+		imports = append(imports, buildImportSpec(entry))
+	}
+	file.Imports = imports
+}
+
+func buildImportDecl(entries []importEntry) *ast.GenDecl {
+	specs := make([]ast.Spec, 0, len(entries))
+	for _, entry := range entries {
+		specs = append(specs, buildImportSpec(entry))
+	}
+
+	decl := &ast.GenDecl{
+		Tok:   token.IMPORT,
+		Specs: specs,
+	}
+	if len(entries) > 1 {
+		decl.Lparen = token.Pos(1)
+		decl.Rparen = token.Pos(1)
+	}
+	return decl
+}
+
+func buildImportSpec(entry importEntry) *ast.ImportSpec {
+	spec := &ast.ImportSpec{
+		Path: &ast.BasicLit{Kind: token.STRING, Value: entry.pathValue},
+	}
+	if entry.name != "" {
+		spec.Name = ast.NewIdent(entry.name)
+	}
+	if entry.original.Comment != nil {
+		spec.Comment = entry.original.Comment
+	}
+	return spec
+}
+
+func printFile(fset *token.FileSet, file *ast.File) ([]byte, error) {
+	var buf bytes.Buffer
+	cfg := printer.Config{Mode: printer.UseSpaces | printer.TabIndent, Tabwidth: 8}
+	if err := cfg.Fprint(&buf, fset, file); err != nil {
+		return nil, err
+	}
+	return buf.Bytes(), nil
+}
+
+func needsGroupedImportRewrite(segments [][]importEntry) bool {
+	return len(segments) > 1
+}
+
+func buildGroupedImportBlock(segments [][]importEntry) string {
+	var b strings.Builder
+	b.WriteString("import (\n")
+	for i, segment := range segments {
+		if i > 0 {
+			b.WriteString("\n")
+		}
+		for _, entry := range segment {
+			b.WriteString("\t")
+			if entry.name != "" {
+				b.WriteString(entry.name)
+				b.WriteString(" ")
+			}
+			b.WriteString(entry.pathValue)
+			if entry.inline != "" {
+				b.WriteString("\t")
+				b.WriteString(entry.inline)
+			}
+			b.WriteString("\n")
+		}
+	}
+	b.WriteString(")")
+	return b.String()
+}
+
+func replaceNonCImportDecl(src []byte, replacement string) ([]byte, error) {
+	fset := token.NewFileSet()
+	file, err := parser.ParseFile(fset, "", src, parser.ParseComments)
+	if err != nil {
+		return nil, err
+	}
+
+	for _, decl := range file.Decls {
+		gen, ok := decl.(*ast.GenDecl)
+		if !ok || gen.Tok != token.IMPORT {
+			continue
+		}
+		hasNonC := false
+		for _, spec := range gen.Specs {
+			if strings.Trim(spec.(*ast.ImportSpec).Path.Value, `"`) != "C" {
+				hasNonC = true
+				break
+			}
+		}
+		if !hasNonC {
+			continue
+		}
+
+		start := fset.Position(gen.Pos()).Offset
+		end := fset.Position(gen.End()).Offset
+		out := make([]byte, 0, len(src)-((end-start)-len(replacement)))
+		out = append(out, src[:start]...)
+		out = append(out, replacement...)
+		out = append(out, src[end:]...)
+		return out, nil
+	}
+
+	return src, nil
+}
+
+func cloneImportDecl(gen *ast.GenDecl) *ast.GenDecl {
+	clone := &ast.GenDecl{
+		Doc:    gen.Doc,
+		TokPos: gen.TokPos,
+		Tok:    gen.Tok,
+		Lparen: gen.Lparen,
+		Rparen: gen.Rparen,
+	}
+	for _, spec := range gen.Specs {
+		clone.Specs = append(clone.Specs, spec)
+	}
+	return clone
+}
+
+func singleImportDecl(spec *ast.ImportSpec, doc *ast.CommentGroup) *ast.GenDecl {
+	return &ast.GenDecl{
+		Doc:   doc,
+		Tok:   token.IMPORT,
+		Specs: []ast.Spec{spec},
+	}
+}
+
+func joinCommentGroup(group *ast.CommentGroup) string {
+	parts := make([]string, 0, len(group.List))
+	for _, comment := range group.List {
+		parts = append(parts, comment.Text)
+	}
+	return strings.Join(parts, " ")
+}
+
+func validOutputMode(value string) bool {
+	return value == "file" || value == "write" || value == "stdout"
+}
+
+func inferProjectName(filePath string) (string, error) {
+	dir := filepath.Dir(filePath)
+	for {
+		goMod := filepath.Join(dir, "go.mod")
+		data, err := os.ReadFile(goMod)
+		if err == nil {
+			module := parseModulePath(data)
+			if module != "" {
+				return module, nil
+			}
+			break
+		}
+		if !errors.Is(err, fs.ErrNotExist) {
+			return "", err
+		}
+		parent := filepath.Dir(dir)
+		if parent == dir {
+			break
+		}
+		dir = parent
+	}
+	return "", fmt.Errorf("open go.mod: no such file or directory")
+}
+
+func parseModulePath(data []byte) string {
+	for _, line := range strings.Split(string(data), "\n") {
+		line = strings.TrimSpace(line)
+		if line == "" || strings.HasPrefix(line, "//") {
+			continue
+		}
+		if strings.HasPrefix(line, "module ") {
+			fields := strings.Fields(line)
+			if len(fields) >= 2 {
+				return strings.Trim(fields[1], "\"`")
+			}
+		}
+	}
+	return ""
+}
+
+func isGeneratedFile(data []byte) bool {
+	for _, line := range strings.Split(string(data), "\n") {
+		line = strings.TrimSpace(line)
+		if line == "" {
+			continue
+		}
+		return strings.HasPrefix(line, "// Code generated")
+	}
+	return false
+}
+
+func (p *processor) expandInput(input string) ([]string, error) {
+	if strings.HasSuffix(input, "/...") || input == "..." {
+		base := strings.TrimSuffix(input, "/...")
+		if base == "" {
+			base = "."
+		}
+		return p.walkGoFiles(base, true)
+	}
+
+	info, err := os.Stat(input)
+	if err != nil {
+		return nil, err
+	}
+	if !info.IsDir() {
+		abs, err := filepath.Abs(input)
+		if err != nil {
+			return nil, err
+		}
+		if p.isExcluded(filepath.Dir(abs), abs) {
+			return nil, nil
+		}
+		return []string{abs}, nil
+	}
+
+	return p.walkGoFiles(input, p.cfg.recursive)
+}
+
+func (p *processor) walkGoFiles(root string, recursive bool) ([]string, error) {
+	rootAbs, err := filepath.Abs(root)
+	if err != nil {
+		return nil, err
+	}
+
+	var files []string
+	if !recursive {
+		entries, err := os.ReadDir(rootAbs)
+		if err != nil {
+			return nil, err
+		}
+		for _, entry := range entries {
+			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".go") {
+				continue
+			}
+			full := filepath.Join(rootAbs, entry.Name())
+			if p.isExcluded(rootAbs, full) {
+				continue
+			}
+			files = append(files, full)
+		}
+		sort.Strings(files)
+		return files, nil
+	}
+
+	err = filepath.WalkDir(rootAbs, func(current string, d fs.DirEntry, walkErr error) error {
+		if walkErr != nil {
+			return walkErr
+		}
+		if d.IsDir() {
+			if current != rootAbs && p.isExcluded(rootAbs, current) {
+				return filepath.SkipDir
+			}
+			return nil
+		}
+		if !strings.HasSuffix(d.Name(), ".go") {
+			return nil
+		}
+		if p.isExcluded(rootAbs, current) {
+			return nil
+		}
+		files = append(files, current)
+		return nil
+	})
+	if err != nil {
+		return nil, err
+	}
+
+	sort.Strings(files)
+	return files, nil
+}
+
+func (p *processor) isExcluded(root, target string) bool {
+	if len(p.cfg.excludes) == 0 {
+		return false
+	}
+
+	rel, err := filepath.Rel(root, target)
+	if err != nil {
+		return false
+	}
+	rel = filepath.ToSlash(rel)
+
+	for _, raw := range p.cfg.excludes {
+		pattern := filepath.ToSlash(strings.TrimSpace(raw))
+		if pattern == "" {
+			continue
+		}
+
+		if strings.HasSuffix(pattern, "/") {
+			prefix := strings.TrimSuffix(pattern, "/")
+			if rel == prefix || strings.HasPrefix(rel, prefix+"/") {
+				return true
+			}
+			continue
+		}
+
+		if !strings.ContainsAny(pattern, "*?[") {
+			if rel == pattern || strings.HasPrefix(rel, pattern+"/") || path.Base(rel) == pattern {
+				return true
+			}
+			continue
+		}
+
+		if ok, _ := path.Match(pattern, rel); ok {
+			return true
+		}
+	}
+
+	return false
+}
