package main

import (
	"errors"
	"flag"
	"fmt"
	"log"
	"os"
)

const (
	versionString = "3.0.0-20260303205914-9926ea38658f"
	versionInfo   = "version: 3.0.0-20260303205914-9926ea38658f\n" +
		"built with: go1.26.0\n" +
		"tag: v3.0.0-20260303205914-9926ea38658f\n" +
		"commit: n/a\n" +
		"source: github.com/incu6us/goimports-reviser/v3\n"
)

func main() {
	log.SetFlags(log.Ldate | log.Ltime)

	cfg, fs, err := parseFlags(os.Args)
	if err != nil {
		if errors.Is(err, flag.ErrHelp) {
			os.Exit(0)
		}
		os.Exit(2)
	}

	if cfg.versionOnly {
		_, _ = os.Stdout.WriteString(versionString + "\n")
		return
	}

	if cfg.version {
		_, _ = os.Stdout.WriteString(versionInfo)
		return
	}

	if err := cfg.validate(); err != nil {
		fs.Usage()
		log.Printf("%v", err)
		os.Exit(1)
	}

	if len(cfg.paths) == 0 {
		fs.Usage()
		log.Printf("no file(s) or directory(ies) specified on input")
		os.Exit(1)
	}

	log.Printf("Paths: %v", cfg.paths)

	processor := newProcessor(cfg, fs)
	exitCode := processor.run()

	if cfg.usedLocal {
		log.Printf("-local is deprecated and will be removed soon. Use -company-prefixes instead.")
		log.Printf("All changes to file are applied, but command-line syntax should be fixed")
		exitCode = 1
	}

	if cfg.filePath != "" {
		log.Printf("-file-path is deprecated. Put file name(s) as last argument to the command(Example: goimports-reviser -rm-unused -set-alias -format goimports-reviser/main.go)")
		log.Printf("All changes to file are applied, but command-line syntax should be fixed")
		exitCode = 1
	}

	os.Exit(exitCode)
}

