package main

import (
	"bytes"
	"context"
	"encoding/json"
	"os/exec"
	"path/filepath"
)

type packageInfo struct {
	names map[string]string
}

type goListPackage struct {
	ImportPath string
	Name       string
}

func loadPackageInfo(ctx context.Context, dir string) (*packageInfo, []byte, error) {
	cmd := exec.CommandContext(ctx, "go", "list", "-deps", "-json", ".")
	cmd.Dir = dir

	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		return nil, stderr.Bytes(), err
	}

	info := &packageInfo{names: map[string]string{}}
	decoder := json.NewDecoder(&stdout)
	for {
		var pkg goListPackage
		if err := decoder.Decode(&pkg); err != nil {
			if err.Error() == "EOF" {
				break
			}
			return nil, stderr.Bytes(), err
		}
		if pkg.ImportPath == "" || pkg.Name == "" {
			continue
		}
		info.names[pkg.ImportPath] = pkg.Name
	}
	return info, stderr.Bytes(), nil
}

func packageDir(filePath string) string {
	return filepath.Dir(filePath)
}

